const takeWriteLock = `-- name: TakeWriteLock :exec
SELECT pg_advisory_xact_lock($1::bigint)
`

// The write lock is the analog of beginning a SQLite transaction immediate: a rule
// reads and then writes, and what it read has to hold at commit.
func (q *Queries) TakeWriteLock(ctx context.Context, lockKey int64) error {
	_, err := q.db.Exec(ctx, takeWriteLock, lockKey)
	return err
}

